L["Increases your critical strike chance with ranged weapons by 1%."] = "Erhöht Eure Chance, mit Distanzwaffen einen kritischen Treffer zu erzielen, um 1%."
L["Increases your damage with Wands by 13%."] = "Erhöht Eure Schadenswirkung mit Zauberstäben um 13%."
